#[test]
fn sqlite_snapshot_pptx_exact_profile_policies_use_typed_root_namespace_entities(){
 let plan:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛡️profile/🔣️.json")).unwrap();let limits=SqliteDatabaseLimits::default();for case in plan["cases"].as_array().unwrap(){let snapshot=profile_fixture(case);let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.stdio.pptx".into(),standard:"ecma-376".into(),subset:case["subset"].as_str().unwrap().into()};let db=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let result=snapshot.validate_sqlite_snapshot_subset(&dialect,&db,&mut SqliteSnapshotControl::new(&mut |_|true,limits));assert_eq!(result.is_ok(),case["codes"].as_array().unwrap().len()==case["warnings"].as_u64().unwrap()as usize,"{}",case["id"]);let diagnostics=match result{Ok(outcome)=>outcome.diagnostics,Err(error)=>error.diagnostics};assert_eq!(diagnostics.iter().map(|item|item.code.0.as_str()).collect::<Vec<_>>(),case["codes"].as_array().unwrap().iter().map(|item|item.as_str().unwrap()).collect::<Vec<_>>(),"{}",case["id"]);assert_eq!(diagnostics.iter().filter(|item|item.severity==dsl::Severity::Warning).count(),case["warnings"].as_u64().unwrap()as usize);snapshot.retire_sqlite_snapshot();}
}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_pptx_actual_exact_profile_declarations_preserve_owned_warnings(){
 use semio_framework_os_kernel::io::io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot};semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("PPTX exact profiles").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let plan:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛡️profile/🔣️.json")).unwrap();let limits=SqliteDatabaseLimits::default();for case in plan["cases"].as_array().unwrap().iter().filter(|case|case["codes"].as_array().unwrap().len()==case["warnings"].as_u64().unwrap()as usize){let snapshot=profile_fixture(case);let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.stdio.pptx".into(),standard:"ecma-376".into(),subset:case["subset"].as_str().unwrap().into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let exported=io_export_sqlite_snapshot(&dialect,&snapshot,encoding,limits,&mut |_|true).await.unwrap();assert_eq!(exported.diagnostics.len(),case["warnings"].as_u64().unwrap()as usize);let restored=io_import_sqlite_snapshot::<PptxSnapshot>(&dialect,&exported.value,limits,&mut |_|true).await.unwrap();assert_eq!(restored.value,snapshot);assert_eq!(restored.diagnostics.len(),exported.diagnostics.len());let foreign=store::io_schema::ArtifactDialect{subset:if dialect.subset=="strict"{"transitional".into()}else{"strict".into()},..dialect.clone()};assert!(io_import_sqlite_snapshot::<PptxSnapshot>(&foreign,&exported.value,limits,&mut |_|true).await.is_err());restored.value.retire_sqlite_snapshot();}snapshot.retire_sqlite_snapshot();}
}
#[test]
fn sqlite_snapshot_pptx_native_grammar_describes_complete_owned_fields(){let snapshot=fixture();let text=<PptxSnapshot as store::ArtifactDsl>::print_dsl(&snapshot);let(envelope,body)=store::semio_format::split_text_preamble(&text).unwrap();let grammar=semio_framework_os_kernel::parse_grammar(crate::schema::snapshot::text::COMPONENT_GRAMMAR_SEMIO).unwrap();assert!(semio_framework_os_kernel::Recognizer::compile(&grammar).recognize(&format!("{}\n{body}",envelope.envelope_id())).unwrap());snapshot.retire_sqlite_snapshot();}
#[test]
fn sqlite_snapshot_pptx_native_protocol_checks_complete_literal_fields(){
 let snapshot=fixture();let bytes=<PptxSnapshot as store::ArtifactPack>::encode_pack(&snapshot);let(_,body)=store::semio_format::unwrap_binary(&bytes).unwrap();
 let protocol=semio_framework_os_kernel::parse_protocol(crate::schema::snapshot::binary::COMPONENT_PROTOCOL_SEMIO).unwrap();
 assert_eq!(semio_framework_os_kernel::walk_protocol(&protocol,&body).unwrap().consumed,body.len());
 for length in[0,1,body.len()-1]{assert!(semio_framework_os_kernel::walk_protocol(&protocol,&body[..length]).is_err());}
 let mut trailing=body.clone();trailing.push(0);assert!(semio_framework_os_kernel::walk_protocol(&protocol,&trailing).is_err());snapshot.retire_sqlite_snapshot();
}
fn fixture()->PptxSnapshot{store::json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap()}
