#[test]
fn sqlite_snapshot_pptx_exact_aggregate_row_budget(){let snapshot=fixture();let defaults=SqliteDatabaseLimits::default();let db=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,defaults)).unwrap();let count=db.tables.iter().map(|table|table.rows.len()).sum::<usize>();let exact=SqliteDatabaseLimits{max_rows:count,..defaults};assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,exact)).is_ok());assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:count-1,..defaults})).is_err());}

#[test]
fn sqlite_snapshot_pptx_rejects_dangling_and_shared_package_owners(){let snapshot=fixture();let limits=SqliteDatabaseLimits::default();let db=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for(table,row,column,value)in[("pptx_document",0,2,SqliteValue::Integer(2)),("pptx_xml_part",1,4,SqliteValue::Integer(1)),("pptx_relationship",0,1,SqliteValue::Integer(99)),("pptx_default_content_type",0,2,SqliteValue::Integer(99)),("pptx_relationship_owner",1,2,SqliteValue::Text("".into()))]{let mut invalid=db.clone();invalid.table_mut(table).unwrap().rows[row].values[column]=value;assert!(PptxSnapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err(),"{table}");}}
#[test]
fn sqlite_snapshot_pptx_literal_large_part_bytes_have_interior_controls(){let mut snapshot=fixture();snapshot.opc.parts[0].bytes=vec![0x97;100000];let limits=SqliteDatabaseLimits::default();let db=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot]{let mut observed=false;let mut callback=|event:SqliteSnapshotProgress|{if event.phase==phase&&event.total==100000&&event.completed>=65536&&event.completed<event.total{observed=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,limits);let failed=if phase==SqliteSnapshotPhase::ProjectSnapshot{snapshot.to_sqlite_database(&mut control).is_err()}else{PptxSnapshot::from_sqlite_database(&db,&mut control).is_err()};assert!(failed);assert!(observed);}}
#[test]
fn sqlite_snapshot_pptx_partial_part_reconstruction_retires_deep_completed_documents(){std::thread::Builder::new().stack_size(256*1024).spawn(||{struct Owned(Option<PptxSnapshot>);impl Drop for Owned{fn drop(&mut self){if let Some(snapshot)=self.0.take(){snapshot.retire_sqlite_snapshot();}}}let mut snapshot=fixture();let mut node=semio_s_artifact_stdio_xml::schema::snapshot::XmlNode::Text{text:"leaf".into()};for _ in 0..8192{node=semio_s_artifact_stdio_xml::schema::snapshot::XmlNode::Element{name:"node".into(),attrs:Vec::new(),children:vec![node]};}snapshot.xml_parts[0].document.root=Some(node);snapshot.xml_parts[1].content_type="z".repeat(100000);let snapshot=Owned(Some(snapshot));let limits=SqliteDatabaseLimits::default();let db=snapshot.0.as_ref().unwrap().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let mut observed=false;assert!(PptxSnapshot::from_sqlite_database(&db,&mut SqliteSnapshotControl::new(&mut |event|{if event.phase==SqliteSnapshotPhase::ReconstructSnapshot&&event.total==100000&&event.completed>=65536&&event.completed<event.total{observed=true;false}else{true}},limits)).is_err());assert!(observed);let restored=PptxSnapshot::from_sqlite_database(&db,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();restored.retire_sqlite_snapshot();}).unwrap().join().unwrap();}
#[semio_framework_async_macros::async_test]
