#[test]
fn sqlite_snapshot_pptx_complete_signed64_transform_domain(){let snapshot=fixture();let PptxShape::TextBox{position,..}=&snapshot.presentation.slides[0].shapes[0]else{panic!("typed transform fixture")};assert_eq!(*position,PptxTransform{x:i64::MIN,y:i64::MAX,cx:9007199254740993,cy:-9007199254740993});let limits=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let row=&database.table("pptx_transform").unwrap().rows[0];assert_eq!(row.integer(1).unwrap(),i64::MIN);assert_eq!(row.integer(2).unwrap(),i64::MAX);let restored=PptxSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored,snapshot);restored.retire_sqlite_snapshot();snapshot.retire_sqlite_snapshot();}

#[test]
fn sqlite_snapshot_pptx_actual_erased_native_boundaries_retain_all_owned_fields(){let snapshot=fixture();let limits=SqliteDatabaseLimits::default();let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.stdio.pptx".into(),standard:"ecma-376".into(),subset:"*".into()};let codec=<PptxSnapshot as ArtifactSqliteSnapshot>::sqlite_codec();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let db=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let payload=(codec.import)(crate::STDIO_PPTX_DOCUMENT_SCHEMA,&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let projected=(codec.export)(crate::STDIO_PPTX_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let restored=PptxSnapshot::from_sqlite_database(&projected,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored,snapshot);restored.retire_sqlite_snapshot();}snapshot.retire_sqlite_snapshot();}
#[test]
fn sqlite_snapshot_pptx_deep_erased_native_input_output_are_interior_cancellable(){let plan:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛫️native/🔣️.json")).unwrap();std::thread::Builder::new().stack_size(plan["smallStackBytes"].as_u64().unwrap()as usize).spawn(move||{struct Owner(Option<PptxSnapshot>);impl Drop for Owner{fn drop(&mut self){if let Some(snapshot)=self.0.take(){snapshot.retire_sqlite_snapshot();}}}let mut snapshot=fixture();let mut node=semio_s_artifact_stdio_xml::schema::snapshot::XmlNode::Text{text:"leaf".into()};for _ in 0..plan["depth"].as_u64().unwrap(){node=semio_s_artifact_stdio_xml::schema::snapshot::XmlNode::Element{name:"node".into(),attrs:vec![],children:vec![node]};}snapshot.xml_parts[0].document.root=Some(node);let mut other=semio_s_artifact_stdio_xml::schema::snapshot::XmlNode::Text{text:"other leaf".into()};for _ in 0..plan["depth"].as_u64().unwrap(){other=semio_s_artifact_stdio_xml::schema::snapshot::XmlNode::Element{name:"other node".into(),attrs:vec![],children:vec![other]};}snapshot.presentation.slides[0].shapes.push(PptxShape::Other{node:other});snapshot.xml_parts[1].content_type="z".repeat(plan["lateTextBytes"].as_u64().unwrap()as usize);let snapshot=Owner(Some(snapshot));let limits=SqliteDatabaseLimits::default();let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.stdio.pptx".into(),standard:"ecma-376".into(),subset:"*".into()};let codec=<PptxSnapshot as ArtifactSqliteSnapshot>::sqlite_codec();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let db=snapshot.0.as_ref().unwrap().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let expected_database=db.clone();let payload=(codec.import)(crate::STDIO_PPTX_DOCUMENT_SCHEMA,&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let projected=(codec.export)(crate::STDIO_PPTX_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert!(projected==expected_database,"complete deep native graph differs");assert_eq!(projected.table("pptx_xml_element").unwrap().rows.iter().filter(|row|row.text(1).unwrap()=="node").count(),plan["depth"].as_u64().unwrap()as usize);assert_eq!(projected.table("pptx_xml_text").unwrap().rows.iter().filter(|row|row.text(1).unwrap()=="leaf").count(),1);assert_eq!(projected.table("pptx_xml_element").unwrap().rows.iter().filter(|row|row.text(1).unwrap()=="other node").count(),plan["depth"].as_u64().unwrap()as usize);assert_eq!(projected.table("pptx_xml_text").unwrap().rows.iter().filter(|row|row.text(1).unwrap()=="other leaf").count(),1);for phase in[SqliteSnapshotPhase::EncodeNative,SqliteSnapshotPhase::DecodeNative]{let mut reached=false;let mut callback=|event:SqliteSnapshotProgress|{if event.phase==phase&&event.completed>=plan["cancelAfter"].as_u64().unwrap()as usize&&event.completed<event.total{reached=true;false}else{true}};let failed=if phase==SqliteSnapshotPhase::EncodeNative{let db=snapshot.0.as_ref().unwrap().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();(codec.import)(crate::STDIO_PPTX_DOCUMENT_SCHEMA,&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut callback,limits)).is_err()}else{(codec.export)(crate::STDIO_PPTX_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut callback,limits)).is_err()};assert!(failed);assert!(reached,"actual interior native phase {phase:?}");}}}).unwrap().join().unwrap();}

#[test]
fn sqlite_snapshot_pptx_native_exact_file_and_entity_admission(){
 let snapshot=fixture();let defaults=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,defaults)).unwrap();let rows=database.tables.iter().map(|table|table.rows.len()).sum::<usize>();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,defaults)).unwrap();let bytes=match &payload{store::io_schema::IoPayload::Binary(bytes)=>bytes.len(),store::io_schema::IoPayload::Text(text)=>text.len()};let exact=SqliteDatabaseLimits{max_file_bytes:bytes,max_rows:rows,..defaults};assert_eq!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),payload);let restored=PptxSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap();assert_eq!(restored,snapshot);restored.retire_sqlite_snapshot();
 for limited in[SqliteDatabaseLimits{max_file_bytes:bytes-1,..exact},SqliteDatabaseLimits{max_rows:rows-1,..exact}]{assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limited)).is_err());assert!(PptxSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limited)).is_err());}
 }snapshot.retire_sqlite_snapshot();
}

#[test]
fn sqlite_snapshot_pptx_complete_literal_native_file_matches_independent_fixture(){let plan:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🧩️native-literals/🔣️.json")).unwrap();let snapshot:PptxSnapshot=store::json::from_json_str(&plan["snapshot"].to_string()).unwrap();let defaults=SqliteDatabaseLimits::default();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let expected=if encoding==SnapshotEncoding::Binary{store::io_schema::IoPayload::Binary(plan["binary"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u8).collect())}else{store::io_schema::IoPayload::Text(plan["text"].as_str().unwrap().into())};let file_size=match &expected{store::io_schema::IoPayload::Binary(bytes)=>bytes.len(),store::io_schema::IoPayload::Text(text)=>text.len()};let limits=SqliteDatabaseLimits{max_file_bytes:file_size,max_rows:plan["rows"].as_u64().unwrap()as usize,..defaults};assert_eq!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);let restored=PptxSnapshot::decode_sqlite_snapshot_native(&expected,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored,snapshot);restored.retire_sqlite_snapshot();}snapshot.retire_sqlite_snapshot();}
